function minStartValue(nums) {
  for (let start = 1; ; start++) {
    let running = start;
    let ok = true;
    for (let i = 0; i < nums.length && ok; i++) {
      running += nums[i];
      if (running < 1) ok = false;
    }
    if (ok) return start;
  }
}

