function generate(rand, size) {
  if (size === 'large') {
    const n = 100;
    const mode = rand();
    // Mostly negative values push the answer toward its maximum; mixed values keep it moderate.
    const bias = mode < 0.4 ? -60 : mode < 0.7 ? 0 : 30;
    return [Array.from({ length: n }, () => Math.max(-100, Math.min(100, bias + Math.floor(rand() * 201) - 100)))];
  }
  const n = 1 + Math.floor(rand() * 8);
  const span = rand() < 0.5 ? 5 : 100;
  return [Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span)];
}
